      seq: i + 1,
      turn: fact.turn,
      step: fact.step,
      purpose: fact.purpose,
      provider: fact.provider,
      model: fact.model,
      status: fact.status,
      startedAt: fact.startedAt,
      completedAt: fact.completedAt,
      usage: fact.usage,
