+  final List<List<T>> _chunks = <List<T>>[<T>[]];
+  final List<int> _chunkEpoch = <int>[0];
+  int _length = 0;
+  int _epoch = 0;
+
+  /// Total row references copied into published/cloned structures over
+  /// this store's life — the deterministic cost metric for the #1497
+  /// scaling guard.
