+  /// Drops everything (builder reset).
+  void reset() {
+    _chunks.length = 1;
+    _chunks[0] = <T>[];
+    _chunkEpoch.length = 1;
+    _chunkEpoch[0] = _epoch;
+    _length = 0;
+    copiedRows = 0;
+  }
