            cacheRead: 30,
            cacheWrite: 5,
            reasoning: 8,
            totalTokens: 163,
            cost: UsageCost(),
          ),
      stopReason: stopReason,
      errorMessage: errorMessage,
      timestamp: _at(1),
    ),
  );
}

